import os,re,json
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
print(sorted(G))

def objects(g):
    seen=set(); objs=[]
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c] and (r,c) not in seen:
                col=g[r][c]; stack=[(r,c)]; seen.add((r,c)); cells=[]
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<len(g) and 0<=nx<len(g[0]) and (ny,nx) not in seen and g[ny][nx]==col:
                            seen.add((ny,nx)); stack.append((ny,nx))
                objs.append(cells)
    return objs

def transform(g):
    g=[row[:] for row in g]; H,W=len(g),len(g[0])
    objs=objects(g)
    objs.sort(key=lambda o:-max(c for r,c in o))
    out=[[0]*W for _ in range(H)]
    for obj in objs:
        best=0
        for s in range(1,W):
            ok=all(c+s<W and out[r][c+s]==0 for r,c in obj)
            if ok: best=s
            else: break
        for r,c in obj: out[r][c+best]=g[r][c]
    return out

o=transform(G['Demo pair 1 input'])
print(o==G['Demo pair 1 output'])
print(json.dumps(transform(G['Test input'])))

